head.b:skin:
/* 
THEME: Intimate Narrative & Wellness (Velvet Edition)
SYSTEM: Adult Fiction & Sex-Education Framework
*/
:root {
    --velvet: #2d0b1a;
    --rose-gold: #b76e79;
    --silk: #f8f1f1;
    --noir: #1a1a1a;
    --wine: #5c1a2c;
}
body {
    background-color: var(--noir);
    color: var(--silk);
    font-family: 'Montserrat', sans-serif;
    margin: 0; padding: 0;
    line-height: 1.6;
}
.header-wrap {
    background: linear-gradient(180deg, var(--velvet), var(--noir));
    color: var(--rose-gold);
    padding: 60px 20px;
    text-align: center;
    border-bottom: 2px solid var(--rose-gold);
}
.header-wrap h1 { font-family: 'Playfair Display', serif; font-size: 32px; letter-spacing: 3px; margin-bottom: 10px; }
.main-container {
    max-width: 800px;
    margin: -30px auto 60px;
    padding: 20px;
}
.intimate-card {
    background: #251018;
    border-radius: 15px;
    box-shadow: 0 10px 40px rgba(0,0,0,0.5);
    padding: 40px;
    margin-bottom: 25px;
    border: 1px solid rgba(183, 110, 121, 0.2);
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 10px;
    color: var(--rose-gold);
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 2px;
}
.input-group input, .input-group textarea, .input-group select {
    width: 100%;
    padding: 14px;
    border: 1px solid var(--rose-gold);
    border-radius: 8px;
    font-family: 'Inter', sans-serif;
    box-sizing: border-box;
    background: #1a080f;
    color: var(--silk);
}
.input-group textarea { height: 100px; resize: vertical; }

.options-row { display: flex; gap: 20px; flex-wrap: wrap; }
.flex-item { flex: 1; min-width: 200px; }

h2 { color: var(--rose-gold); text-align: center; font-family: 'Playfair Display', serif; font-style: italic; font-size: 26px; }

.copy-btn {
    background: var(--rose-gold);
    color: var(--velvet);
    border: none;
    padding: 18px;
    cursor: pointer;
    font-weight: bold;
    width: 100%;
    border-radius: 8px;
    transition: 0.4s;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 2px;
}
.copy-btn:hover { background: var(--silk); color: var(--velvet); box-shadow: 0 0 20px rgba(183, 110, 121, 0.4); }
footer { text-align: center; color: #555; padding: 30px; font-size: 12px; letter-spacing: 2px; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "An Unforgettable Night";
    var notes = document.getElementById("inputNotes").value || "Focus on healthy communication and sensory connection.";
    var length = document.getElementById("inputLength").value;
    var lang = document.getElementById("inputLang").value;

    var template = (lang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateEN").innerText;

    var finalPrompt = template
        .replace("[USER_TITLE]", title)
        .replace("[USER_NOTES]", notes)
        .replace(/\[USER_LENGTH\]/g, length);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("🌹 Intimate Prompt (" + length + ") copied! Keep it private and safe.");
}
